// The routes. Screen agents do not edit this file: each route already points at the
// component its folder exports.

import { HashRouter, Navigate, Route, Routes } from 'react-router';
import { AppLayout } from './frame';
import { get, topDiagram } from './model/queries';
import { CLINIC } from './sample/clinic';
import { CrudScreen, DataModelScreen } from './screens/datamodel';
import { DictionaryScreen } from './screens/dictionary';
import { OutlineScreen } from './screens/outline';
import { ExportScreen, HelpScreen, ProblemsScreen, ProjectScreen, SearchScreen } from './screens/project';
import { UseCasesScreen } from './screens/usecases';
import { WorkspaceScreen } from './screens/workspace';
import { useModel } from './store/store';

/** Opens the sample's child diagram, which is the screen the briefs put first, or else the project's top diagram. */
function Home() {
  const model = useModel();
  const start = get(model, CLINIC.child1, 'diagram') ?? topDiagram(model);
  return <Navigate replace to={start ? `/diagram/${start.id}` : '/problems'} />;
}

export function App() {
  return (
    <HashRouter>
      <Routes>
        <Route element={<AppLayout />}>
          <Route index element={<Home />} />
          <Route path="use-cases" element={<UseCasesScreen />} />
          <Route path="use-cases/:id" element={<UseCasesScreen />} />
          <Route path="diagram/:diagramId" element={<WorkspaceScreen />} />
          <Route path="diagram/:diagramId/outline" element={<OutlineScreen />} />
          <Route path="dictionary" element={<DictionaryScreen />} />
          <Route path="dictionary/:dataId" element={<DictionaryScreen />} />
          <Route path="data-model" element={<DataModelScreen />} />
          <Route path="crud" element={<CrudScreen />} />
          <Route path="search" element={<SearchScreen />} />
          <Route path="project" element={<ProjectScreen />} />
          <Route path="problems" element={<ProblemsScreen />} />
          <Route path="help" element={<HelpScreen />} />
          <Route path="export" element={<ExportScreen />} />
          <Route path="*" element={<Home />} />
        </Route>
      </Routes>
    </HashRouter>
  );
}
